-- Connect as Azure AD admin and run:
CREATE USER [my-app] FROM EXTERNAL PROVIDER;
ALTER ROLE db_datareader ADD MEMBER [my-app];
ALTER ROLE db_datawriter ADD MEMBER [my-app];

using Azure.Identity;
using Microsoft.Data.SqlClient;

var connectionString = "Server=tcp:my-sql.database.windows.net,1433;Database=myDb;";
var credential = new DefaultAzureCredential();
var token = credential.GetToken(
    new TokenRequestContext(new[] { "https://database.windows.net/.default" })
);

using var conn = new SqlConnection(connectionString);
conn.AccessToken = token.Token;
await conn.OpenAsync();

using var cmd = new SqlCommand("SELECT GETDATE()", conn);
var result = await cmd.ExecuteScalarAsync();
Console.WriteLine(`SQL time: {result}`);
